/* Shared family progress: authenticated requests only; RLS owns authorization. */
const AUTH_RETURN_URL='https://mason-trainer-adventure.vercel.app/';
const authReturnParams=new URLSearchParams(location.hash.slice(1));
const incomingAuthError=authReturnParams.get('error_code')||authReturnParams.get('error');
function authErrorMessage(error){return /expired|invalid|otp_expired|access_denied|already.*used/i.test(String(error?.message||error))?'This sign-in link has expired or was already used. Request a fresh email below and use only the newest link. Open it once, on the device you want to connect.':String(error?.message||error||'Unable to sign in. Please request a new email.')}
const sb=window.supabase.createClient('https://dwuvciahzdnetqkmdqwx.supabase.co','sb_publishable_IiGqUkBqg8j44X9QUWefrg_bWKKWe-o',{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
let cloudUser=null,cloudBusy=false,cloudPending=false,cloudBase=null,cloudTimer,cloudMessage='Device only',authStarted=false;
const rawRender=render,rawSettings=settings,rawBind=bind,rawRedeem=redeem;
function checkResult(r){if(r.error)throw r.error;return r.data}
function cloudBanner(){let e=document.querySelector('#cloudbar');if(!e){e=document.createElement('div');e.id='cloudbar';document.querySelector('nav').after(e)}e.innerHTML=`<span>${cloudUser?'☁ '+esc(cloudMessage):'☁ Connect your family to share progress across devices'}</span><button id="cloudConnect">${cloudUser?'Family connection':'Set up family sync'}</button>`;e.querySelector('button').onclick=cloudPanel}
function backupCache(){if(cloudUser){localStorage.setItem('mason-family-'+cloudUser.id,JSON.stringify(state));localStorage.setItem('mason-pending-'+cloudUser.id,cloudPending?'1':'0')}else localStorage.setItem(KEY,JSON.stringify(state))}
save=function(){cloudPending=!!cloudUser;backupCache();cloudMessage='Saving…';cloudBanner();clearTimeout(cloudTimer);if(cloudUser)cloudTimer=setTimeout(()=>pushCloud().catch(syncError),350)};
function syncError(e){cloudMessage='Not synced · '+(e.message||'Connection unavailable');cloudBanner();toast('Progress stays on this device. Open Family connection to retry.');backupCache()}
function dataDetails(d){let {awards,...details}=d;return details}
async function pushCloud(){if(!cloudUser||cloudBusy)return;cloudBusy=true;try{while(cloudPending){cloudPending=false;const snap=JSON.parse(JSON.stringify(state)),u=cloudUser.id;checkResult(await sb.from('mason_trainer_families').upsert({user_id:u,settings:snap.settings},{onConflict:'user_id'}));
let details=Object.entries(snap.days).filter(([k,d])=>JSON.stringify(dataDetails(d))!==JSON.stringify(cloudBase?.days[k]?dataDetails(cloudBase.days[k]):null)).map(([k,d])=>({user_id:u,day:k,details:dataDetails(d)}));if(details.length)checkResult(await sb.from('mason_trainer_days').upsert(details,{onConflict:'user_id,day'}));
const awards=Object.entries(snap.days).flatMap(([k,d])=>d.awards.map(m=>({user_id:u,day:k,mission:m})));if(awards.length)checkResult(await sb.from('mason_trainer_awards').upsert(awards,{onConflict:'user_id,day,mission',ignoreDuplicates:true}));
for(const r of snap.spent)checkResult(await sb.from('mason_trainer_redemptions').upsert({user_id:u,id:r.id,cost:r.cost,label:r.label,day:r.date},{onConflict:'user_id,id',ignoreDuplicates:true}));
let claims=Object.keys(snap.claims).filter(k=>snap.claims[k]).map(k=>({user_id:u,week:k}));if(claims.length)checkResult(await sb.from('mason_trainer_claims').upsert(claims,{onConflict:'user_id,week',ignoreDuplicates:true}));cloudBase=snap;backupCache();}
cloudMessage='Saved to family cloud';cloudBanner();}catch(e){cloudPending=true;throw e}finally{cloudBusy=false;backupCache()}}
async function readCloudTable(t){let rows=[];for(let offset=0;;offset+=1000){let q=sb.from(t).select('*');if(t==='mason_trainer_awards')q=q.order('day').order('mission');else if(t==='mason_trainer_days')q=q.order('day');else if(t==='mason_trainer_redemptions')q=q.order('id');else if(t==='mason_trainer_claims')q=q.order('week');else q=q.order('user_id');let r=await q.range(offset,offset+999);checkResult(r);rows.push(...r.data);if(r.data.length<1000)return {data:rows,error:null}}}
async function pullCloud(){if(!cloudUser||cloudBusy||cloudPending)return;cloudBusy=true;try{const [f,ds,aw,rs,cs]=await Promise.all(['mason_trainer_families','mason_trainer_days','mason_trainer_awards','mason_trainer_redemptions','mason_trainer_claims'].map(readCloudTable));[f,ds,aw,rs,cs].forEach(checkResult);let next=empty();if(f.data[0])next.settings={...next.settings,...f.data[0].settings};for(const r of ds.data)next.days[r.day]={awards:[],checks:{},...r.details};for(const r of aw.data){if(!next.days[r.day])next.days[r.day]={awards:[],checks:{}};next.days[r.day].awards.push(r.mission)}next.spent=rs.data.map(r=>({id:r.id,cost:r.cost,label:r.label,date:r.day}));next.claims=Object.fromEntries(cs.data.map(r=>[r.week,true]));
// Preserve changes made while requests were in flight; retry upload instead of replacing them.
if(cloudPending)return;state=next;cloudBase=JSON.parse(JSON.stringify(next));backupCache();cloudMessage='Synced · '+new Date().toLocaleTimeString([],{hour:'numeric',minute:'2-digit'});if(!document.querySelector('#dialog').open)render();else cloudBanner();}finally{cloudBusy=false}}
function mergeProgress(remote,local){let r=JSON.parse(JSON.stringify(remote));for(const[k,d]of Object.entries(local.days)){let old=r.days[k];r.days[k]={...d,...old,awards:[...new Set([...(old?.awards||[]),...d.awards])]}}r.spent=[...new Map([...local.spent,...r.spent].map(x=>[x.id,x])).values()];r.claims={...local.claims,...r.claims};return r}
async function connectSession(session){if(!session?.user){cloudUser=null;cloudMessage='Device only';render();return}if(cloudUser?.id===session.user.id)return;cloudUser=session.user;let cached=localStorage.getItem('mason-family-'+cloudUser.id);let pending=localStorage.getItem('mason-pending-'+cloudUser.id)==='1';const old=JSON.parse(localStorage.getItem(KEY)||'null');state=cached?JSON.parse(cached):empty();cloudPending=pending;if(pending){await pushCloud()}await pullCloud();if(!cached&&old&&Object.values(old.days||{}).some(d=>d.awards?.length)){modal('<h2>Bring your points along?</h2><p>Your device has existing Trainer progress. Merge it into your family’s cloud record? Points for the same mission and date are counted only once.</p><button class="primary" id="mergeLocal">Merge existing progress</button><button id="skipLocal">Keep cloud progress only</button>');document.querySelector('#mergeLocal').onclick=async()=>{state=mergeProgress(state,old);save();document.querySelector('#dialog').close();render();await pushCloud().catch(syncError)};document.querySelector('#skipLocal').onclick=()=>document.querySelector('#dialog').close()}render()}
function cloudPanel(){modal(`<h2>${cloudUser?'Family connection':'Connect your family'}</h2>${cloudUser?`<p>Signed in as <b>${esc(cloudUser.email)}</b></p><p>Sign in with this same parent email on Mason’s device. His completed missions will appear in your Parent dashboard. Both devices share family access; Trainer mode is a simpler view, not a separate restricted child account.</p><div class="notice">${esc(cloudMessage)}</div><button class="primary" id="retryCloud">Sync now</button><button id="signoutCloud" style="margin-top:12px">Sign out on this device</button>`:`<p>Use the same parent email on both devices. Sign in once on Mason’s device, then let him use Daily missions.</p><form id="sendLogin"><label class="field">Parent email<input type="email" id="familyEmail" autocomplete="email" required></label><button class="primary">Email a sign-in link</button></form><div id="authNotice" class="notice" hidden></div><form id="verifyLogin"><label class="field">Sign-in code or copied email link<input id="emailToken" autocomplete="one-time-code" placeholder="Paste the link or code from the email" required></label><button class="primary">Connect this device</button></form><p class="muted">If the email contains a link, copy its full address and paste it above. Use an unused link from the newest email. Opening it first can use it up.</p>`}`);
if(cloudUser){document.querySelector('#retryCloud').onclick=async()=>{try{await pushCloud();await pullCloud();document.querySelector('#dialog').close();render();toast('Family progress synced')}catch(e){syncError(e)}};document.querySelector('#signoutCloud').onclick=async()=>{if(cloudPending){await pushCloud().catch(syncError);if(cloudPending)return}await sb.auth.signOut({scope:'local'});cloudUser=null;cloudBase=null;state=JSON.parse(localStorage.getItem(KEY)||'null')||empty();document.querySelector('#dialog').close();render()};return}
document.querySelector('#sendLogin').onsubmit=async e=>{e.preventDefault();const email=document.querySelector('#familyEmail').value.trim();let note=document.querySelector('#authNotice');note.hidden=false;note.textContent='Sending…';try{checkResult(await sb.auth.signInWithOtp({email,options:{shouldCreateUser:true,emailRedirectTo:AUTH_RETURN_URL}}));note.textContent='Check your email and open the NEWEST sign-in link on this device. The link works once. You can also paste its original address below without opening it first.';const send=e.target.querySelector('button');send.disabled=true;let remaining=60;const timer=setInterval(()=>{remaining--;send.textContent=remaining>0?'Request another in '+remaining+'s':'Email a new sign-in link';if(remaining<=0){clearInterval(timer);send.disabled=false}},1000)}catch(e){note.textContent=authErrorMessage(e)}};
document.querySelector('#verifyLogin').onsubmit=async e=>{e.preventDefault();let email=document.querySelector('#familyEmail').value.trim(),token=document.querySelector('#emailToken').value.trim(),args;try{if(token.startsWith('http')){let u=new URL(token);if(u.protocol!=='https:')throw Error('Use the original HTTPS sign-in link from the email.');if(u.hostname!=='dwuvciahzdnetqkmdqwx.supabase.co')throw Error('Use the sign-in link from this app’s Supabase email.');let hash=u.searchParams.get('token')||u.searchParams.get('token_hash');if(!hash)throw Error('Copy the original sign-in link from the email, before opening it.');args={token_hash:hash,type:'email'}}else args={email,token,type:'email'};let res=await sb.auth.verifyOtp(args);checkResult(res);document.querySelector('#dialog').close();await connectSession(res.data.session);toast('Family sync connected')}catch(e){let note=document.querySelector('#authNotice');note.hidden=false;note.textContent=authErrorMessage(e)}}}
render=function(){rawRender();if(view==='parent')parentDashboard();cloudBanner()};
settings=function(){rawSettings();let b=document.createElement('button');b.textContent=cloudUser?'Family connection & sync':'Connect family cloud';b.onclick=cloudPanel;document.querySelector('#dialogContent').prepend(b);let n=document.querySelector('#dialogContent .notice');if(n)n.textContent='When family sync is connected, progress is shared across devices. Backups remain available. Importing merges earned points into cloud history.'};
bind=function(){rawBind();let claim=document.querySelector('#claim');if(claim&&cloudUser)claim.onclick=async()=>{try{await pushCloud();if(cloudPending||cloudBusy)throw Error('Wait for pending sync, then retry.');checkResult(await sb.from('mason_trainer_claims').upsert({user_id:cloudUser.id,week:monday(date)},{onConflict:'user_id,week',ignoreDuplicates:true}));await pullCloud();toast('Target reward recorded. Savings unchanged!')}catch(e){toast(e.message)}}};
redeem=function(id){if(!cloudUser)return rawRedeem(id);let cost={local:100,super:200,legendary:300}[id];modal(`<h2>Confirm your adventure</h2><p>With a grown-up, confirm <b>${esc(state.settings[id])}</b>, the budget, and the date. This spends ${cost} points.</p><button class="primary" id="cloudRedeem">Grown-up confirms · spend ${cost} points</button><div id="redeemError" role="status"></div>`);const rid=crypto.randomUUID();document.querySelector('#cloudRedeem').onclick=async e=>{e.target.disabled=true;try{await pushCloud();if(cloudPending||cloudBusy)throw Error('Wait for pending sync, then retry.');checkResult(await sb.from('mason_trainer_redemptions').upsert({user_id:cloudUser.id,id:rid,cost,label:state.settings[id],day:today()},{onConflict:'user_id,id',ignoreDuplicates:true}));await pullCloud();document.querySelector('#dialog').close();render();toast('Adventure redeemed!')}catch(err){document.querySelector('#redeemError').textContent=err.message;e.target.disabled=false}}};
function parentDashboard(){const start=monday(date),w=weekly(start),last=Array.from({length:14},(_,i)=>shift(today(),-i));document.querySelector('#content').innerHTML=`<div class="topline"><div><h2>Parent dashboard</h2><div class="muted">Mason’s missions, scores, and reward history</div></div><button id="parentRefresh">Refresh progress</button></div>${!cloudUser?'<div class="notice">Connect family sync to see progress from Mason’s device. This view currently shows only this browser.</div>':''}<div class="grid3"><div class="card"><div class="tiny-label">TODAY</div><div class="score">${day(today()).awards.length}<small> / 5</small></div><p class="muted">Missions completed</p></div><div class="card"><div class="tiny-label">THIS WEEK</div><div class="score">${weekly(monday(today()))}<small> / 35</small></div><p class="muted">25 points unlocks Target</p></div><div class="card"><div class="tiny-label">ADVENTURE BANK</div><div class="score">${bank()}</div><p class="muted">${sum()} earned · ${sum()-bank()} spent</p></div></div><div class="card history"><h3>Last 14 days</h3><div class="table-scroll"><table><thead><tr><th>Date</th>${missions.map(m=>`<th>${esc(m[2])}</th>`).join('')}<th>Score</th></tr></thead><tbody>${last.map(d=>`<tr><td>${esc(dt(d).toLocaleDateString(undefined,{month:'short',day:'numeric'}))}</td>${missions.map(m=>`<td aria-label="${esc(m[2])}: ${day(d).awards.includes(m[0])?'complete':'not complete'}">${day(d).awards.includes(m[0])?'✓':'–'}</td>`).join('')}<td><b>${day(d).awards.length}/5</b></td></tr>`).join('')}</tbody></table></div></div><div class="card history"><h3>Mission totals · last 14 days</h3>${missions.map(m=>`<p><span>${esc(m[2])}</span><b>${last.filter(d=>day(d).awards.includes(m[0])).length}/14</b></p>`).join('')}</div><div class="card history"><h3>Recent rewards</h3>${state.spent.slice().reverse().map(r=>`<p><span>${esc(r.label)} · ${esc(r.date)}</span><b>−${r.cost}</b></p>`).join('')||'<p>No adventures redeemed yet.</p>'}<p class="muted">${Object.keys(state.claims).filter(k=>state.claims[k]).length} weekly Target rewards recorded</p></div>`;document.querySelector('#parentRefresh').onclick=async()=>{try{await pushCloud();await pullCloud();render();toast(cloudUser?'Progress refreshed':'Connect family sync to share progress')}catch(e){syncError(e)}}}
let parentNav=document.createElement('button');parentNav.textContent='▦ Parent view';parentNav.dataset.view='parent';parentNav.onclick=()=>{view='parent';render()};document.querySelector('nav').append(parentNav);
window.addEventListener('online',()=>pushCloud().then(pullCloud).catch(syncError));document.addEventListener('visibilitychange',()=>{if(!document.hidden)pushCloud().then(pullCloud).catch(syncError)});setInterval(()=>{if(!document.hidden&&!document.querySelector('#dialog').open)pushCloud().then(pullCloud).catch(syncError)},15000);
sb.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_OUT'){cloudUser=null;cloudBase=null;render()}else if(event==='SIGNED_IN')setTimeout(()=>connectSession(session).catch(syncError),0)});sb.auth.getSession().then(async({data,error})=>{if(error||incomingAuthError){history.replaceState(null,'',location.pathname);cloudPanel();const note=document.querySelector('#authNotice');if(note){note.hidden=false;note.textContent=authErrorMessage(error||incomingAuthError)}return}await connectSession(data.session);if(data.session&&location.hash)history.replaceState(null,'',location.pathname)}).catch(e=>{cloudPanel();const note=document.querySelector('#authNotice');if(note){note.hidden=false;note.textContent=authErrorMessage(e)}});render();
